-- Spec 286 T3: o envio automatico do boleto por WhatsApp ao cliente. Aditiva: a trava `claimed_at` (nula em toda linha
-- existente) e dois motivos novos (`client_without_whatsapp`, `template_missing`); nenhuma linha muda.
ALTER TABLE "occurrence_contractor_reply_deliveries" ADD COLUMN "claimed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "occurrence_contractor_reply_deliveries" DROP CONSTRAINT "occurrence_contractor_reply_deliveries_reason_check", ADD CONSTRAINT "occurrence_contractor_reply_deliveries_reason_check" CHECK ("reason" in ('driver_without_account', 'driver_unreachable', 'whatsapp_window_closed', 'note_without_recipient_email', 'attachment_too_large_for_email', 'send_failed', 'client_without_email', 'whatsapp_number_not_found', 'whatsapp_disconnected', 'attachment_too_large_for_whatsapp', 'client_without_whatsapp', 'template_missing'));--> statement-breakpoint
ALTER TABLE "occurrence_contractor_reply_events" DROP CONSTRAINT "occurrence_contractor_reply_events_reason_check", ADD CONSTRAINT "occurrence_contractor_reply_events_reason_check" CHECK ("reason" in ('no_accepted_attachment', 'multiple_attachments', 'document_not_confirmed', 'driver_without_account', 'driver_unreachable', 'whatsapp_window_closed', 'note_without_recipient_email', 'attachment_too_large_for_email', 'send_failed', 'client_without_email', 'whatsapp_number_not_found', 'whatsapp_disconnected', 'attachment_too_large_for_whatsapp', 'client_without_whatsapp', 'template_missing', 'document_confirmed', 'document_without_text'));